from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            area = (r1-r0+1) * (c1-c0+1)
            # Rectangular objects are interrupted by stray colored pixels; infer and restore their bounding box.
            if area >= 4 and len(cells) / area >= 0.65:
                boxes.append((len(cells), len(cells)/area, color, r0, r1, c0, c1))
    out = [[bg] * w for _ in range(h)]
    # Stronger/larger rectangle evidence wins any overlap.
    for _, _, color, r0, r1, c0, c1 in sorted(boxes):
        for y in range(r0, r1+1):
            for x in range(c0, c1+1):
                out[y][x] = color
    return out

